		// ── client/live-data.mjs ──────────────────────────────────────
/**
 * Live official data for the changelog panel.
 *
 * Two public sources, both verified to allow browser use:
 *
 * - `https://registry.npmjs.org/@deepseek-ai/dsh-base` — every published
 *   version with its exact publish time, plus the dist-tags. Authoritative for
 *   "which releases exist", including the ones that never got release notes.
 * - `https://api.github.com/repos/deepseek-ai/deepseek-harness/releases` — the
 *   official release notes. These are **bilingual by construction**: every note
 *   carries a `[中文](#cn-…) | [English](#en-…)` header and two parallel
 *   sections, so the Chinese shown for a live release is the project's own
 *   Chinese, not our translation.
 *
 * Both return `access-control-allow-origin: *`, so the browser can call them
 * directly; no host half and no proxy are involved.
 *
 * Everything here is a pure function over fetched JSON so it can be tested
 * without a network.
 *
 * @module dsh-changelog-panel/live-data
 */

/** npm package whose version list defines "which releases exist". */
const NPM_PACKAGE = '@deepseek-ai/dsh-base'
/** GitHub repository that publishes the official release notes. */
const GITHUB_REPO = 'deepseek-ai/deepseek-harness'
/** Release tags are `<TAG_PREFIX><version>`. */
const TAG_PREFIX = 'dsh-v'

const RELEASES_URL = `https://api.github.com/repos/${GITHUB_REPO}/releases?per_page=100`
const REGISTRY_URL = `https://registry.npmjs.org/${encodeURIComponent(NPM_PACKAGE)}`

const REQUEST_TIMEOUT_MS = 20000
/** GitHub's unauthenticated budget is 60 requests/hour; below this we back off. */
const RATE_LIMIT_FLOOR = 5

// ── release-note parsing ────────────────────────────────────────────────────

/** Heading text → the panel's category vocabulary. */
const CATEGORY_PATTERNS = [
  [/新增|new feature|features?\b/i, 'new'],
  [/体验优化|improvement|enhance/i, 'improved'],
  [/问题修复|bug\s*fix|fixes?\b/i, 'fixed'],
  [/其他变更|other change|chores?\b/i, 'other'],
]
/**
 * Order release-note categories render in. Named apart from the panel's own
 * `CATEGORY_ORDER` (feature topics) because both files are concatenated into one
 * bundle scope, where a shared name would be a redeclaration.
 */
const NOTE_CATEGORY_ORDER = ['new', 'improved', 'fixed', 'other']

/** Strip markdown emphasis and inline code, keeping the words. */
function stripInline(text) {
  return String(text)
    .replace(/`([^`]*)`/g, '$1')
    .replace(/\*\*([^*]+)\*\*/g, '$1')
    .replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')
    .replace(/\s+/g, ' ')
    .trim()
}

/**
 * Split `@handle` mentions from an item's prose.
 *
 * The English notes write attribution as `… by @handle`, so the lead-in word has
 * to go with the handle; removing only the mention leaves a dangling "by".
 * @param text - one item's text.
 * @returns `{ text, credits }`.
 */
function splitCredits(text) {
  const credits = []
  const body = String(text).replace(
    /(?:\s*\b(?:by|thanks to|credit(?:s)? to)\s*)?@([A-Za-z0-9][A-Za-z0-9-]*)/gi,
    (_match, handle) => {
      credits.push(handle)
      return ''
    },
  )
  return {
    text: body
      .replace(/\s+([,，。.；;：:])/g, '$1')
      // The Chinese notes separate attribution with an em dash ("… — @handle"),
      // which would otherwise be left dangling once the handle is removed.
      .replace(/[\s,，、;；:：]*(?:—|–|-{1,2})[\s]*$/g, '')
      .replace(/\s{2,}/g, ' ')
      .trim(),
    credits,
  }
}

/** Map a heading to a category key, defaulting to `other`. */
function categoryOf(heading) {
  for (const [pattern, key] of CATEGORY_PATTERNS) if (pattern.test(heading)) return key
  return 'other'
}

/**
 * Block-level normalization before line parsing.
 *
 * The official notes are hand-written HTML-in-markdown and do **not** reliably
 * put one element per line: an `<h3>` heading can be glued to the end of the
 * previous bullet, and anchors share a line with their heading. Splitting on the
 * tags themselves makes the line grammar trustworthy; parsing line-by-line
 * without this swallowed headings into bullet text.
 * @param section - raw section text.
 * @returns one element per line.
 */
function toBlockLines(section) {
  return String(section)
    .replace(/<h([1-6])\b/gi, '\n<h$1')
    .replace(/<\/h[1-6]>/gi, '</h3>\n')
    .replace(/<a\s+id=/gi, '\n<a id=')
    // Both heading styles occur in the same note: the first category is an HTML
    // `<h3>`, every later one is markdown `###`. Missing the second style merged
    // all four categories into the first, which is exactly what happened before
    // this line existed.
    .replace(/^[ \t]*#{1,6}[ \t]+/gm, '\n### ')
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter((line) => line !== '')
}

/** Parse one language section into categorized items. */
function parseSection(section) {
  const groups = []
  let current = null
  const openGroup = (text) => {
    current = { category: categoryOf(text), heading: text, items: [] }
    groups.push(current)
    return current
  }
  for (const line of toBlockLines(section)) {
    // A heading of any level, possibly with trailing prose on the same line.
    const headingMatches = [...line.matchAll(/<h[1-6][^>]*>([\s\S]*?)<\/h[1-6]>/gi)]
    if (headingMatches.length > 0) {
      for (const match of headingMatches) {
        const text = stripInline(match[1])
        if (text !== '') openGroup(text)
      }
      continue
    }
    const markdownHeading = /^###\s+(.*)$/.exec(line)
    if (markdownHeading) {
      const text = stripInline(markdownHeading[1])
      if (text !== '') openGroup(text)
      continue
    }
    // Navigation links and anchors are structural, never content.
    if (/^<a\s/i.test(line) || /^\[/.test(line) || /^<\/?(?:p|div|ul|ol|li|br)\b/i.test(line)) continue
    const bullet = /^[-*]\s+(.*)$/.exec(line)
    if (bullet) {
      const item = splitCredits(stripInline(bullet[1]))
      if (item.text === '') continue
      if (current === null) openGroup('')
      current.items.push(item)
      continue
    }
    // A continuation line extends the bullet above it.
    if (current !== null && current.items.length > 0) {
      const last = current.items[current.items.length - 1]
      const extra = splitCredits(stripInline(line))
      if (extra.text !== '') {
        last.text = (last.text + ' ' + extra.text).trim()
        last.credits = last.credits.concat(extra.credits)
      }
    }
  }
  return groups.filter((group) => group.items.length > 0)
}

/**
 * Anchors that mark the start of each language half.
 *
 * The project has used at least three shapes across its history, and all three
 * occur in the published notes, so a narrow pattern silently drops real Chinese:
 *   `<h3 id="cn-v0.2.0-rc.2-community">`   (current, suffixed)
 *   `<h2 id="chinese">`                    (`0.1.3-alpha.2`)
 *   `<h3 id="cn">`                         (`0.1.0-rc.7`)
 * Matching only the first form left two releases with no Chinese at all.
 */
const ZH_ANCHOR = /<h[1-6][^>]*\bid="[^"]*\b(?:cn|zh|chinese)\b[^"]*"/i
const EN_ANCHOR = /<h[1-6][^>]*\bid="[^"]*\b(?:en|eng|english)\b[^"]*"/i

/**
 * Split a release body into its Chinese and English halves.
 *
 * The notes link both languages at the top and mark each half with an anchored
 * heading; a body with no Chinese anchor yields `null` and the caller falls back
 * rather than guessing.
 * @param body - the raw `body` field of a GitHub release.
 * @returns `{ zh, en }` section text, each possibly empty, or null.
 */
function splitBilingual(body) {
  if (typeof body !== 'string' || body === '') return null
  const cnAt = body.search(ZH_ANCHOR)
  const enAt = body.search(EN_ANCHOR)
  if (cnAt === -1 && enAt === -1) return null
  // An English-only note is a real note. Returning null here would classify it as
  // "the project published nothing", which hides content and states a falsehood;
  // the panel has a separate message for "notes exist but carry no Chinese".
  if (cnAt === -1) return { zh: '', en: body.slice(enAt) }
  if (enAt === -1) return { zh: body.slice(cnAt), en: '' }
  return cnAt < enAt
    ? { zh: body.slice(cnAt, enAt), en: body.slice(enAt) }
    : { zh: body.slice(cnAt), en: body.slice(enAt, cnAt) }
}

/**
 * Parse one GitHub release into the panel's row shape.
 * @param release - a raw GitHub release object.
 * @returns a parsed release row, or null when the tag is not one of ours.
 */
function parseGithubRelease(release) {
  if (!release || typeof release.tag_name !== 'string') return null
  if (release.tag_name.indexOf(TAG_PREFIX) !== 0) return null
  const version = release.tag_name.slice(TAG_PREFIX.length)
  const split = splitBilingual(release.body)
  const zh = split ? parseSection(split.zh) : []
  const en = split ? parseSection(split.en) : []
  return {
    version,
    tag: release.tag_name,
    title: typeof release.name === 'string' && release.name !== '' ? release.name : version,
    publishedAt: typeof release.published_at === 'string' ? release.published_at : null,
    url: typeof release.html_url === 'string' ? release.html_url : null,
    prerelease: release.prerelease === true,
    /** Categories present in the Chinese notes, with English wording filled in per item. */
    groups: mergeLanguages(zh, en),
    /** Whether the official notes carry Chinese at all. */
    hasChinese: zh.length > 0,
    /** Whether the official notes exist in any language. */
    hasNotes: zh.length > 0 || en.length > 0,
  }
}

/**
 * Merge the two language sections into one ordered group list.
 *
 * Sections are aligned by position, which is how the project writes them, and
 * each item keeps both languages so the panel's language switch works on live
 * data exactly as it does on the bundled dataset.
 * @param zh - parsed Chinese groups.
 * @param en - parsed English groups.
 * @returns merged groups.
 */
function mergeLanguages(zh, en) {
  const byCategory = new Map()
  const push = (group, index, language) => {
    const key = group.category + '#' + index
    if (!byCategory.has(key)) {
      byCategory.set(key, { category: group.category, heading: { zh: '', en: '' }, items: [] })
    }
    const target = byCategory.get(key)
    target.heading[language] = group.heading
    return target
  }
  zh.forEach((group, index) => {
    const target = push(group, index, 'zh')
    group.items.forEach((item, itemIndex) => {
      const other = en[index] && en[index].items[itemIndex]
      target.items.push({
        key: group.category + '-' + index + '-' + itemIndex,
        text: { zh: item.text, en: other ? other.text : '' },
        credits: item.credits.length > 0 ? item.credits : other ? other.credits : [],
      })
    })
  })
  // English sections with no Chinese counterpart (a partially translated note).
  en.forEach((group, index) => {
    if (zh[index]) return
    const target = push(group, index, 'en')
    group.items.forEach((item, itemIndex) => {
      target.items.push({
        key: group.category + '-' + index + '-' + itemIndex,
        text: { zh: '', en: item.text },
        credits: item.credits,
      })
    })
  })
  return [...byCategory.values()]
    .filter((group) => group.items.length > 0)
    .sort((a, b) => NOTE_CATEGORY_ORDER.indexOf(a.category) - NOTE_CATEGORY_ORDER.indexOf(b.category))
}

// ── merging the two sources ─────────────────────────────────────────────────

/**
 * Build the live release list from the registry and the release notes.
 *
 * The registry is the spine: it knows every published version and its exact
 * date. Notes are attached where they exist. A version with no release notes is
 * kept and flagged, because "no official notes exist" is information the reader
 * needs, not a row to silently drop.
 * @param registry - parsed npm registry document.
 * @param releases - parsed GitHub release rows.
 * @returns `{ releases, distTags }`.
 */
function mergeReleases(registry, releases) {
  const times = registry && registry.time && typeof registry.time === 'object' ? registry.time : {}
  const versions = registry && registry.versions && typeof registry.versions === 'object' ? registry.versions : {}
  const byVersion = new Map(releases.map((row) => [row.version, row]))

  const rows = Object.keys(versions)
    .filter((version) => typeof times[version] === 'string')
    .sort((a, b) => (times[a] < times[b] ? 1 : times[a] > times[b] ? -1 : 0))
    .map((version) => {
      const notes = byVersion.get(version)
      return {
        version,
        date: times[version].slice(0, 10),
        publishedAt: times[version],
        latestFor: distTagsFor(registry, version),
        notes: notes
          ? { groups: notes.groups, url: notes.url, hasChinese: notes.hasChinese, hasNotes: notes.hasNotes }
          : null,
      }
    })

  // A release note for a version the registry does not list (e.g. an
  // unpublished tag) is still worth showing, so it is appended.
  for (const row of releases) {
    if (rows.some((entry) => entry.version === row.version)) continue
    rows.push({
      version: row.version,
      date: row.publishedAt ? row.publishedAt.slice(0, 10) : '',
      publishedAt: row.publishedAt,
      latestFor: [],
      notes: { groups: row.groups, url: row.url, hasChinese: row.hasChinese, hasNotes: row.hasNotes },
    })
  }
  // Rows appended from a note-only version have no registry date; sort them last
  // so the list is still strictly newest-first rather than "dated, then leftovers".
  rows.sort((a, b) => {
    const left = a.publishedAt || ''
    const right = b.publishedAt || ''
    if (left === right) return 0
    if (left === '') return 1
    if (right === '') return -1
    return left < right ? 1 : -1
  })
  return { releases: rows, distTags: (registry && registry['dist-tags']) || {} }
}

/**
 * Which dist-tags point at a version.
 * @param registry - parsed npm registry document.
 * @param version - version to test.
 * @returns tag names.
 */
function distTagsFor(registry, version) {
  const tags = (registry && registry['dist-tags']) || {}
  return Object.keys(tags).filter((tag) => tags[tag] === version)
}

// ── fetching ────────────────────────────────────────────────────────────────

/** Fetch JSON with a timeout and a caller-supplied abort signal. */
async function fetchJson(url, signal) {
  const controller = typeof AbortController === 'function' ? new AbortController() : null
  const timer = setTimeout(() => {
    if (controller) controller.abort()
  }, REQUEST_TIMEOUT_MS)
  const onAbort = () => {
    if (controller) controller.abort()
  }
  if (signal && typeof signal.addEventListener === 'function') signal.addEventListener('abort', onAbort)
  try {
    const response = await fetch(url, {
      signal: controller ? controller.signal : signal,
      headers: { accept: 'application/json' },
    })
    const remaining = Number(response.headers && response.headers.get && response.headers.get('x-ratelimit-remaining'))
    const body = await response.json().catch(() => null)
    return { ok: response.ok, status: response.status, body, remaining: Number.isFinite(remaining) ? remaining : null }
  } finally {
    clearTimeout(timer)
    if (signal && typeof signal.removeEventListener === 'function') signal.removeEventListener('abort', onAbort)
  }
}

/** Turn a failed fetch into a message a reader can act on. */
function describeFailure(source, status, remaining) {
  if (status === 403 || status === 429) {
    return remaining === 0
      ? `${source}: GitHub API rate limit reached (60 requests/hour without a token). Try again later.`
      : `${source}: request refused (HTTP ${status}).`
  }
  return `${source}: HTTP ${status}`
}

/**
 * Fetch the live official data.
 *
 * The two sources are independent: a failing registry still yields whatever
 * notes were fetched, and vice versa. Rate-limit exhaustion on GitHub is
 * reported as a distinct, actionable status instead of a generic error.
 * @param options - `{ signal }`.
 * @returns `{ releases, distTags, fetchedAt, warnings, rateLimited, latest }`.
 */
async function fetchLiveData(options) {
  const signal = options && options.signal
  const warnings = []
  let rateLimited = false
  let latest = null

  let registry = null
  try {
    const result = await fetchJson(REGISTRY_URL, signal)
    if (result.ok && result.body) registry = result.body
    else warnings.push(describeFailure('npm registry', result.status, result.remaining))
  } catch (error) {
    warnings.push('npm registry: ' + (error && error.message ? error.message : 'request failed'))
  }

  let releases = []
  try {
    const result = await fetchJson(RELEASES_URL, signal)
    if (result.ok && Array.isArray(result.body)) {
      releases = result.body.map(parseGithubRelease).filter(Boolean)
      if (result.remaining !== null && result.remaining <= RATE_LIMIT_FLOOR) rateLimited = true
    } else if (result.status === 403 || result.status === 429) {
      rateLimited = true
      warnings.push(describeFailure('GitHub releases', result.status, result.remaining))
    } else {
      warnings.push(describeFailure('GitHub releases', result.status, result.remaining))
    }
  } catch (error) {
    warnings.push('GitHub releases: ' + (error && error.message ? error.message : 'request failed'))
  }

  const merged = mergeReleases(registry, releases)
  // Both sources failing is a failed refresh, not a successful empty one: the
  // caller must be able to keep showing the data it already has and say so,
  // instead of replacing it with "0 versions".
  if (registry === null && releases.length === 0) {
    throw new Error(warnings.length > 0 ? warnings.join('; ') : 'no source returned data')
  }
  if (merged.releases.length > 0) latest = merged.releases[0].version
  return {
    releases: merged.releases,
    distTags: merged.distTags,
    latest,
    rateLimited,
    warnings,
    fetchedAt: new Date().toISOString(),
  }
}

		// ── client/fetched.mjs ────────────────────────────────────────
/**
 * Live-refresh layer: the refresh state machine, its status line, the "which
 * version am I on" badge, and the fetched release-notes view.
 *
 * Split out of `index.mjs` so the network-facing behaviour can be reasoned about
 * (and tested) on its own. `tests/build.mjs` concatenates this file into one
 * scope with `live-data.mjs` and `index.mjs`, so it imports nothing:
 * `fetchLiveData`, `pickText`, `isArray`, `el` and `React` are plain in-scope
 * bindings, and so are the build-time `RELEASES` and `INSTALLED_VERSION`.
 *
 * Wiring status, checked against the current `index.mjs` and its stylesheet:
 *
 * - No new CSS classes. Every class used here already exists:
 *     .dshcl-ver (badge wrapper), .dshcl-verValue,
 *     .dshcl-verState with .dshcl-verStateOk / Behind / Ahead / Unknown,
 *     .dshcl-live, .dshcl-liveHead, .dshcl-liveTitle, .dshcl-liveControls,
 *     .dshcl-liveBtn,
 *     .dshcl-liveStatus with .dshcl-liveStatusOk / Warn / Error,
 *     .dshcl-liveWarn, .dshcl-liveRelease, .dshcl-liveReleaseHead,
 *     .dshcl-liveDate, .dshcl-liveNoteHead, .dshcl-liveItem,
 *     .dshcl-liveItemText, .dshcl-liveCredits,
 *   plus the shared .dshcl-group, .dshcl-items, .dshcl-count, .dshcl-pill,
 *   .dshcl-tag, .dshcl-empty, .dshcl-ref and .dshcl-ver (release version text).
 *
 * - No new dictionary keys. The keys consumed, all present in the dictionaries:
 *     live.title, live.refresh, live.refreshing, live.auto, live.autoOn,
 *     live.autoOff, live.interval, live.everyMinutes, live.everyHours,
 *     live.lastUpdated, live.neverFetched, live.error, live.rateLimited,
 *     live.warning, live.empty, live.liveVersions, live.officialNotes,
 *     live.noNotes, live.noChinese, live.version.current, live.version.latest,
 *     live.version.upToDate, live.version.behind, live.version.ahead,
 *     live.version.unknown, note.new, note.improved, note.fixed, note.other.
 *   The note.* labels go through `t()`, with `NOTE_CATEGORY_LABEL` (below) as the
 *   fallback for a bundle whose dictionary has not been extended yet.
 *
 * The only Chinese strings that live in this file are the four category labels in
 * `NOTE_CATEGORY_LABEL`; every other word comes from the panel's dictionaries.
 *
 * @module dsh-changelog-panel/fetched
 */

/** How many live releases the list renders; older ones stay reachable in the rail. */
const LIVE_LIST_LIMIT = 12

/**
 * Release-note categories: icon and label, in render order.
 *
 * Exported because these four labels are part of the feature's contract and are
 * the fallback when a dictionary key is missing; the panel's dictionaries win
 * wherever they define `note.<category>`.
 */
const NOTE_CATEGORY_LABEL = {
  new: { icon: '✨', zh: '新增', en: 'New features' },
  improved: { icon: '🎨', zh: '优化', en: 'Improvements' },
  fixed: { icon: '🐛', zh: '修复', en: 'Bug fixes' },
  other: { icon: '⚠️', zh: '其他', en: 'Other changes' },
}

/** Render order for `NOTE_CATEGORY_LABEL`. */
const NOTE_RENDER_ORDER = ['new', 'improved', 'fixed', 'other']

/** Tone name → status-line classes. Tones are the vocabulary `describeRefresh` returns. */
const LIVE_STATUS_CLASS = {
  idle: 'dshcl-liveStatus',
  busy: 'dshcl-liveStatus',
  ok: 'dshcl-liveStatus dshcl-liveStatusOk',
  warn: 'dshcl-liveStatus dshcl-liveStatusWarn',
  error: 'dshcl-liveStatus dshcl-liveStatusError',
}

// ── version comparison ──────────────────────────────────────────────────────

/**
 * Split a version into its numeric core and its prerelease identifiers.
 *
 * Build metadata (`+sha`) is dropped, as semver's precedence rules require, and a
 * value with no numeric core returns null rather than 0.0.0: pretending `abc` is
 * a version would show a bogus "update available" badge instead of admitting the
 * comparison cannot be made.
 * @param version - a semver-ish string.
 * @returns `{ core: number[], pre: (string|number)[] }`, or null.
 */
function parseVersion(version) {
  if (typeof version !== 'string') return null
  const text = version.trim().replace(/^v/i, '')
  if (text === '' || !/^[0-9]/.test(text)) return null
  const withoutBuild = text.split('+')[0]
  const sections = withoutBuild.split('-')
  const parts = sections[0].split('.')
  if (!parts.every((part) => /^[0-9]+$/.test(part))) return null
  const core = parts.map(Number)
  // Everything after the first hyphen is prerelease, hyphens included:
  // '1.0.0-alpha-1' carries one identifier, not two.
  const pre = sections.length > 1
    ? sections
        .slice(1)
        .join('-')
        .split('.')
        .filter((part) => part !== '')
        .map((part) => (/^[0-9]+$/.test(part) ? Number(part) : part))
    : []
  return { core: core, pre: pre }
}

/**
 * Compare two versions by semver precedence.
 *
 * Deliberately small — it only orders published tags — but the prerelease rules
 * are the part that matters and are implemented properly: a prerelease sorts
 * below its release (`0.2.0-rc.2 < 0.2.0`), numeric identifiers compare
 * numerically (`0.2.0-rc.10 > 0.2.0-rc.2`) and rank below alphanumeric ones, and
 * a longer prerelease wins when the shorter is its prefix.
 * @param a - left version.
 * @param b - right version.
 * @returns -1, 0 or 1; null when either side is unparseable.
 */
function compareVersions(a, b) {
  const left = parseVersion(a)
  const right = parseVersion(b)
  if (!left || !right) return null

  const width = Math.max(left.core.length, right.core.length)
  for (let index = 0; index < width; index += 1) {
    const one = left.core[index] === undefined ? 0 : left.core[index]
    const two = right.core[index] === undefined ? 0 : right.core[index]
    if (one !== two) return one < two ? -1 : 1
  }

  // A version with a prerelease tag sorts before the same core without one.
  if (left.pre.length === 0 && right.pre.length === 0) return 0
  if (left.pre.length === 0) return 1
  if (right.pre.length === 0) return -1

  const preWidth = Math.max(left.pre.length, right.pre.length)
  for (let index = 0; index < preWidth; index += 1) {
    const one = left.pre[index]
    const two = right.pre[index]
    if (one === undefined) return -1
    if (two === undefined) return 1
    if (one === two) continue
    const oneNumeric = typeof one === 'number'
    const twoNumeric = typeof two === 'number'
    if (oneNumeric && twoNumeric) return one < two ? -1 : 1
    // Numeric identifiers always sort before alphanumeric ones.
    if (oneNumeric !== twoNumeric) return oneNumeric ? -1 : 1
    return String(one) < String(two) ? -1 : 1
  }
  return 0
}

/**
 * How the installed build relates to the newest known release.
 *
 * `tone` doubles as the class suffix (`dshcl-verStateOk` …), which is why it
 * repeats `relation` rather than being derived a second time at the call site.
 * @param installed - the installed version, or '' when unknown.
 * @param newest - the newest known version, or '' when unknown.
 * @returns `{ relation, tone }`, relation being ok|behind|ahead|unknown.
 */
function versionRelation(installed, newest) {
  const order = compareVersions(installed, newest)
  if (order === null) return { relation: 'unknown', tone: 'unknown' }
  if (order === 0) return { relation: 'ok', tone: 'ok' }
  return order < 0 ? { relation: 'behind', tone: 'behind' } : { relation: 'ahead', tone: 'ahead' }
}

// ── refresh state ───────────────────────────────────────────────────────────

/**
 * Seed the refresh state.
 *
 * A cache restored here is the payload of the last successful fetch, so a
 * reopened panel shows data immediately instead of an empty state; the reader
 * then refreshes when they want fresh numbers.
 * @param cached - a payload restored from `localStorage`, if any.
 * @returns the initial state; an absent or malformed cache yields the idle seed.
 */
function createLiveState(cached) {
  const restored = cached && isArray(cached.releases) && cached.releases.length > 0 ? cached : null
  return {
    status: restored ? 'ok' : 'idle',
    data: restored,
    error: '',
    lastAttemptAt: restored && typeof restored.fetchedAt === 'string' ? restored.fetchedAt : null,
    rateLimited: false,
    warnings: restored && isArray(restored.warnings) ? restored.warnings : [],
  }
}

/**
 * Turn a thrown fetch failure into a message a reader can act on.
 *
 * The transport's own wording is English, exactly like the warnings
 * `live-data.mjs` returns; the status line puts the localized `live.error` label
 * in front of it, so a driver string is never the whole story the reader sees.
 * @param error - the value `fetchLiveData` threw.
 * @returns a one-line message.
 */
function describeRefreshError(error) {
  if (!error) return 'unknown error'
  if (error.name === 'AbortError') return 'refresh aborted'
  if (typeof error.message === 'string' && error.message !== '') return error.message
  return String(error)
}

/**
 * Fetch once and fold the outcome into the state.
 *
 * The caller marks the state `loading` itself before applying this updater,
 * because the in-flight transition has to be visible while the request runs and
 * React state updates are asynchronous:
 *
 *     setLive((current) => ({ ...current, status: 'loading' }))
 *     setLive(await runRefresh({ signal })(currentState))
 *
 * A failed refresh keeps the previous payload: losing the data a reader is
 * already looking at because a network call failed would be worse than showing
 * slightly stale data with a warning.
 * @param options - `{ signal }`, an AbortSignal that cancels the request.
 * @returns an async state reducer `(state) => nextState`.
 */
function runRefresh(options) {
  const signal = options && options.signal
  return async (state) => {
    const previous = state || createLiveState()
    const attemptedAt = new Date().toISOString()
    try {
      const data = await fetchLiveData({ signal: signal })
      return {
        ...previous,
        status: 'ok',
        data: data,
        error: '',
        rateLimited: data && data.rateLimited === true,
        warnings: isArray(data && data.warnings) ? data.warnings : [],
        lastAttemptAt: attemptedAt,
      }
    } catch (error) {
      return {
        ...previous,
        status: 'error',
        error: describeRefreshError(error),
        lastAttemptAt: attemptedAt,
      }
    }
  }
}

// ── describing the state ────────────────────────────────────────────────────

/**
 * A short timestamp in the reader's own time zone, with an explicit offset.
 *
 * The alternative was UTC, which is friendlier to tests and screenshots but asks
 * a reader to convert in their head the one number they actually want ("when did
 * this last update"). The offset is printed rather than named so the output does
 * not depend on a locale-aware formatter.
 * @param iso - an ISO timestamp, or anything else.
 * @param language - 'zh' or 'en'; only the punctuation differs.
 * @returns `YYYY-MM-DD HH:mm UTC±HH:MM`, or '' when the value is not a usable date.
 */
function formatTimestamp(iso, language) {
  if (typeof iso !== 'string' || iso === '') return ''
  const at = new Date(iso)
  if (Number.isNaN(at.getTime())) return ''
  const pad = (value) => String(value).padStart(2, '0')
  const stamp =
    at.getFullYear() +
    '-' +
    pad(at.getMonth() + 1) +
    '-' +
    pad(at.getDate()) +
    ' ' +
    pad(at.getHours()) +
    ':' +
    pad(at.getMinutes())
  // getTimezoneOffset is minutes BEHIND UTC, so its sign is inverted here.
  const offsetMinutes = -at.getTimezoneOffset()
  const sign = offsetMinutes < 0 ? '-' : '+'
  const absolute = Math.abs(offsetMinutes)
  const zone = 'UTC' + sign + pad(Math.floor(absolute / 60)) + ':' + pad(absolute % 60)
  return language === 'zh' ? stamp + '（' + zone + '）' : stamp + ' ' + zone
}

/**
 * Build the status line for the refresh controls.
 *
 * `lastAttemptAt` is reported for every state that has one — including a failed
 * or an in-flight attempt — because "when did we last try" is the fact that makes
 * a stale panel trustworthy or not.
 * @param state - the refresh state.
 * @param t - the panel's translator, bound to the display language.
 * @param language - 'zh' or 'en'.
 * @returns `{ label, tone, detail, canRefresh }`, tone being one of
 *   'idle' | 'busy' | 'ok' | 'warn' | 'error'.
 */
function describeRefresh(state, t, language) {
  const current = state || createLiveState()
  const rows = current.data && isArray(current.data.releases) ? current.data.releases : []
  const warnings = isArray(current.warnings) ? current.warnings : []
  const stamp = formatTimestamp(current.lastAttemptAt, language)
  const timePart = stamp ? t('live.lastUpdated', { time: stamp }) : ''
  // A rate limit or a previous failure still allows a manual retry — the budget
  // may have reset and the reader may know something we do not — so only an
  // in-flight request takes the button away.
  const canRefresh = current.status !== 'loading'

  if (current.status === 'loading') {
    return { label: t('live.refreshing'), tone: 'busy', detail: timePart, canRefresh: false }
  }
  if (current.status === 'error') {
    return {
      label: t('live.error'),
      tone: 'error',
      detail: [timePart, current.error].filter(Boolean).join(' · '),
      canRefresh: canRefresh,
    }
  }
  if (current.status === 'ok' && current.rateLimited) {
    // Distinct from a plain failure: the data is still good, but the notes source
    // is out of budget, and the panel says exactly that instead of "refresh
    // failed" or a silent success.
    return { label: t('live.rateLimited'), tone: 'warn', detail: timePart, canRefresh: canRefresh }
  }
  if (current.status === 'ok') {
    // A lost source is surfaced as a count, not as a different tone: the fetch
    // did succeed, and only rate limiting is a state the reader must act on.
    const detail = warnings.length > 0 ? timePart + ' · ' + t('live.warning') + ' ' + warnings.length : timePart
    return { label: t('live.liveVersions', { n: rows.length }), tone: 'ok', detail: detail, canRefresh: canRefresh }
  }
  return { label: t('live.neverFetched'), tone: 'idle', detail: timePart, canRefresh: canRefresh }
}

// ── version badge ───────────────────────────────────────────────────────────

/**
 * The version this build was made from.
 *
 * The bare identifier is guarded because the bundle is also exercised standalone,
 * and the build bakes in the literal 'unknown' when it cannot read the packaged
 * app — a placeholder that must not be compared as a version.
 * The runtime value (`props.installedVersion`, read from the host report) always
 * wins; the build-time bake is only a fallback.
 * @param props - slot props, optionally carrying `installedVersion`.
 * @returns a version string, or '' when it is unknown.
 */
function installedVersionOf(props) {
  // Runtime first. The bundle also bakes a version in, but that is a build-time
  // snapshot: after the user upgrades the app it names a release they no longer
  // run. The baked value survives only as the fallback for a standalone render.
  const provided = props && typeof props.installedVersion === 'string' ? props.installedVersion : ''
  if (provided !== '' && provided !== 'unknown') return provided
  const baked = typeof INSTALLED_VERSION !== 'undefined' ? INSTALLED_VERSION : ''
  if (typeof baked === 'string' && baked !== '' && baked !== 'unknown') return baked
  return ''
}

/**
 * The newest version known from either source: live data first, then the dataset.
 *
 * Not `RELEASES[0]`: the bundled dataset is authored newest-first but flags the
 * installed build with `highlight`, so array order is presentation rather than a
 * guarantee — the comparator decides, which also covers a live payload whose
 * first row is malformed.
 * @param state - the refresh state, or a live payload.
 * @returns a version string, or '' when neither source has one.
 */
function newestKnownVersion(state) {
  const payload = state && isArray(state.releases) ? state : state && state.data ? state.data : null
  const liveRows = payload && isArray(payload.releases) ? payload.releases : []
  for (const row of liveRows) {
    if (row && typeof row.version === 'string' && row.version !== '') return row.version
  }
  const bundled = typeof RELEASES !== 'undefined' && isArray(RELEASES) ? RELEASES : []
  let best = ''
  for (const row of bundled) {
    const version = row && typeof row.version === 'string' ? row.version : ''
    if (version === '') continue
    if (best === '' || compareVersions(version, best) === 1) best = version
  }
  return best
}

/**
 * The compact "current version" display for the panel header.
 *
 * Shows the installed build, the newest version known from either source, and the
 * relation between them. When either side is unknown the badge says the versions
 * are not comparable instead of claiming the install is current: "we could not
 * compare" and "you are up to date" are different statements and only one of them
 * is true here.
 * @param props - `{ state, t, language }`, plus an optional `installedVersion`.
 * @returns the badge element.
 */
function renderVersionBadge(props) {
  const t = props.t
  const installed = installedVersionOf(props)
  const newest = newestKnownVersion(props.state)
  const { relation, tone } = versionRelation(installed, newest)
  const rows = props.state && props.state.data && isArray(props.state.data.releases) ? props.state.data.releases : []
  const source = rows.length > 0 ? 'live' : 'bundled'
  const stateLabel = {
    ok: t('live.version.upToDate'),
    behind: t('live.version.behind'),
    ahead: t('live.version.ahead'),
    unknown: t('live.version.unknown'),
  }[relation]
  // The tooltip carries what the header row has no space for: both versions and
  // where "newest" came from — a live fetch or the bundled snapshot.
  const title =
    t('live.version.current') +
    ' ' +
    (installed || '—') +
    ' · ' +
    t('live.version.latest') +
    ' ' +
    (newest || '—') +
    (source === 'bundled' ? ' · ' + t('live.neverFetched') : '')
  return el(
    'div',
    { className: 'dshcl-ver', title: title },
    el('span', { className: 'dshcl-verValue' }, installed || '—'),
    newest
      ? el(
          'span',
          { className: 'dshcl-verState dshcl-verState' + tone[0].toUpperCase() + tone.slice(1) },
          stateLabel + ' · ' + t('live.version.latest') + ' ' + newest,
        )
      : el('span', { className: 'dshcl-verState dshcl-verStateUnknown' }, stateLabel),
  )
}

// ── release notes ───────────────────────────────────────────────────────────

/**
 * The visible label for one note category.
 *
 * The dictionaries own the wording — they are the panel's translated surface —
 * and `NOTE_CATEGORY_LABEL` is the fallback for a bundle whose dictionary has not
 * been extended yet. `translateTo` answers a key it cannot resolve with the key
 * itself, which is the signal used here.
 * @param category - a category key, possibly one the panel does not know.
 * @param language - 'zh' or 'en'.
 * @param t - the panel's translator.
 * @returns the label to display.
 */
function noteCategoryLabel(category, language, t) {
  const known = Object.prototype.hasOwnProperty.call(NOTE_CATEGORY_LABEL, category)
  const meta = known ? NOTE_CATEGORY_LABEL[category] : NOTE_CATEGORY_LABEL.other
  const key = 'note.' + (known ? category : 'other')
  const text = t(key)
  return text === key ? (language === 'zh' ? meta.zh : meta.en) : text
}

/**
 * Put one release's note groups in display order, dropping empty ones.
 *
 * `live-data.mjs` sorts already, but a heading the official notes repeat (two
 * "新增" sections in one release) must keep its original relative order, which a
 * plain category sort would lose — hence the index tiebreak.
 * @param groups - parsed note groups.
 * @returns the ordered groups.
 */
function orderNoteGroups(groups) {
  const rank = (category) => {
    const at = NOTE_RENDER_ORDER.indexOf(category)
    return at === -1 ? NOTE_RENDER_ORDER.length : at
  }
  return groups
    .filter((group) => group && isArray(group.items) && group.items.length > 0)
    .map((group, index) => ({ group: group, index: index }))
    .sort((left, right) => rank(left.group.category) - rank(right.group.category) || left.index - right.index)
    .map((entry) => entry.group)
}

/** Sort key for a live release row: its exact publish time when present. */
function stampOf(row) {
  if (!row) return ''
  if (typeof row.publishedAt === 'string' && row.publishedAt !== '') return row.publishedAt
  return typeof row.date === 'string' ? row.date : ''
}

/**
 * Newest release first.
 *
 * `live-data.mjs` already sorts by publish time; this repeats the promise at the
 * render boundary, where a hand-built state (a fixture, a restored cache, a
 * future producer) may hand the rows over in another order. ISO strings compare
 * correctly as strings, and rows without a date keep their order at the end.
 * @param rows - live release rows.
 * @returns a sorted copy.
 */
function newestFirst(rows) {
  return rows
    .map((row, index) => ({ row: row, index: index }))
    .sort((left, right) => {
      const a = stampOf(left.row)
      const b = stampOf(right.row)
      if (a === b) return left.index - right.index
      return a < b ? 1 : -1
    })
    .map((entry) => entry.row)
}

/**
 * One note item: its text in the reader's language, plus attribution tags.
 * @param props - `{ item, language }`.
 * @returns the list item element.
 */
function LiveNoteItem(props) {
  const item = props.item
  const credits = isArray(item.credits) ? item.credits : []
  return el(
    'li',
    { className: 'dshcl-liveItem' },
    el('span', { className: 'dshcl-liveItemText' }, pickText(item.text, props.language)),
    credits.length > 0
      ? el(
          'span',
          { className: 'dshcl-liveCredits' },
          credits.map((handle, index) =>
            el('span', { className: 'dshcl-tag', key: handle + '#' + index }, '@' + handle),
          ),
        )
      : null,
  )
}

/**
 * One release's official notes, grouped by category.
 * @param props - `{ groups, t, language }`.
 * @returns the grouped notes element.
 */
function LiveNoteGroups(props) {
  const groups = orderNoteGroups(isArray(props.groups) ? props.groups : [])
  return el(
    'div',
    null,
    groups.map((group, index) => {
      const meta = NOTE_CATEGORY_LABEL[group.category] || NOTE_CATEGORY_LABEL.other
      const items = isArray(group.items) ? group.items : []
      return el(
        'div',
        // Keyed by position, not by category: the official notes may repeat one
        // category, and two sections with the same key would confuse React.
        { className: 'dshcl-group', key: 'group' + index },
        el(
          'div',
          { className: 'dshcl-liveNoteHead' },
          el('span', { 'aria-hidden': 'true' }, meta.icon),
          el('span', null, noteCategoryLabel(group.category, props.language, props.t)),
          el('span', { className: 'dshcl-count' }, '· ' + items.length),
        ),
        el(
          'ul',
          { className: 'dshcl-items' },
          items.map((item, itemIndex) =>
            el(LiveNoteItem, {
              key: item && item.key ? item.key : 'item' + itemIndex,
              item: item,
              language: props.language,
            }),
          ),
        ),
      )
    }),
  )
}

/**
 * One live release: version, dist-tags, publish date, and its official notes.
 *
 * "The project never published notes for this version" and "the notes exist but
 * carry no Chinese" are different facts, and the reader asked about both, so each
 * version states its own case in the reader's language instead of showing an
 * unexplained gap. Notes that exist only in English are still rendered in the
 * Chinese view (`pickText` falls back), which is why the English-only notice
 * explains the text below it rather than replacing it.
 * @param props - `{ row, t, language }`.
 * @returns the release element.
 */
function renderLiveRelease(props) {
  const row = props.row
  const t = props.t
  const language = props.language === 'zh' ? 'zh' : 'en'
  const notes = row.notes || null
  const groups = notes && isArray(notes.groups) ? notes.groups : []
  const hasNotes = Boolean(notes && notes.hasNotes && groups.length > 0)
  return el(
    'div',
    { className: 'dshcl-liveRelease' },
    el(
      'div',
      { className: 'dshcl-liveReleaseHead' },
      el('span', { className: 'dshcl-ver' }, row.version),
      isArray(row.latestFor) && row.latestFor.length > 0
        ? row.latestFor.map((tag) => el('span', { className: 'dshcl-pill', key: tag }, tag))
        : null,
      row.date ? el('span', { className: 'dshcl-liveDate' }, row.date) : null,
      notes && notes.url
        ? el(
            'a',
            { className: 'dshcl-ref', href: notes.url, target: '_blank', rel: 'noreferrer noopener' },
            t('live.officialNotes'),
          )
        : null,
    ),
    hasNotes ? null : el('p', { className: 'dshcl-liveWarn' }, t('live.noNotes')),
    hasNotes && notes.hasChinese === false
      ? el('p', { className: 'dshcl-liveWarn' }, t('live.noChinese'))
      : null,
    hasNotes ? el(LiveNoteGroups, { groups: groups, t: t, language: language }) : null,
  )
}

// ── the live section ────────────────────────────────────────────────────────

/**
 * The refresh control cluster on its own, so the panel can mount it in its
 * non-scrolling header.
 *
 * The reported bug was that the refresh button travelled with each release's
 * notes: the control sat above the content it refreshes inside the scrolling
 * column, so scrolling a long release pushed it out of reach. Splitting it from
 * `renderLiveNotes` lets the header own it while the section keeps the status
 * line that explains it.
 * @param props - `{ state, t, language, onRefresh }`.
 * @returns the control cluster.
 */
function renderRefreshControls(props) {
  const t = props.t
  const language = props.language === 'zh' ? 'zh' : 'en'
  const state = props.state || createLiveState()
  const status = describeRefresh(state, t, language)
  return el(
    'div',
    { className: 'dshcl-liveControls', 'data-live-controls': 'true' },
    el(
      'button',
      {
        type: 'button',
        className: 'dshcl-liveBtn',
        disabled: !status.canRefresh,
        // The button carries the status as its tooltip, so the reason it is
        // disabled (or what it will do) is reachable without extra chrome.
        title: status.detail || t('live.refresh'),
        onClick: () => {
          if (typeof props.onRefresh === 'function') props.onRefresh()
        },
      },
      status.canRefresh ? t('live.refresh') : t('live.refreshing'),
    ),
    // The last-refresh time belongs next to the control that sets it, and in the
    // header it stays visible while the release notes scroll.
    el(
      'span',
      { className: 'dshcl-liveStatus ' + LIVE_STATUS_CLASS[status.tone] },
      el('span', null, status.label),
      status.detail ? el('span', { className: 'dshcl-liveDate' }, ' · ' + status.detail) : null,
    ),
  )
}

/**
 * The whole live section: controls, status, warnings, and the fetched releases.
 *
 * Purely presentational — it never fetches. The panel owns the state machine: it
 * holds `createLiveState()`, marks the state `loading` and applies `runRefresh()`
 * when a control fires
 * is true. `onToggleAuto` receives the next boolean and `onSetInterval` receives
 * milliseconds, so the panel can store both without re-deriving them from the DOM.
 * @param props - `{ state, t, language, onRefresh, onToggleAuto, onSetInterval }`.
 * @returns the section element.
 */
function renderLiveNotes(props) {
  const t = props.t
  const language = props.language === 'zh' ? 'zh' : 'en'
  const state = props.state || createLiveState()
  const status = describeRefresh(state, t, language)
  const warnings = isArray(state.warnings) ? state.warnings : []
  const rows = newestFirst(state.data && isArray(state.data.releases) ? state.data.releases : [])
  return el(
    'section',
    { className: 'dshcl-live' },
    el(
      'div',
      { className: 'dshcl-liveHead' },
      el('span', { className: 'dshcl-liveTitle' }, t('live.title')),
      // The control cluster itself lives in the panel header (see
      // renderRefreshControls) so it does not travel with a long release's notes.
      el('span', { className: LIVE_STATUS_CLASS[status.tone] }, status.label),
      status.detail ? el('span', { className: 'dshcl-liveDate' }, '· ' + status.detail) : null,
    ),
    warnings.length > 0
      ? el(
          'ul',
          { className: 'dshcl-liveWarn' },
          warnings.map((warning, index) => el('li', { key: 'warn' + index }, warning)),
        )
      : null,
    rows.length === 0
      ? el('p', { className: 'dshcl-liveWarn' }, t('live.empty'))
      : el(
          'div',
          null,
          el(
            'p',
            { className: 'dshcl-liveTitle' },
            t('live.liveVersions', { n: rows.length }),
            // Say that the list is capped, so a reader does not conclude the
            // older releases are missing. They are reachable in the rail.
            rows.length > LIVE_LIST_LIMIT
              ? el('span', { className: 'dshcl-liveDate' }, ' · ' + t('live.showingLatest', { n: LIVE_LIST_LIMIT }))
              : null,
          ),
          // Capping keeps the DOM bounded: one release can carry 90+ items and the
          // registry lists 30+ versions, which is a very large tree for a section
          // whose question is "what changed lately". Older versions stay reachable
          // in the rail.
          rows.slice(0, LIVE_LIST_LIMIT).map((row, index) =>
            renderLiveRelease({ row: row, t: t, language: language, key: row.version || index }),
          ),
        ),
  )
}

		// ── client/storage-panel.mjs ──────────────────────────────────
/**
 * Storage panel: the browser half of the storage / garbage-collection view.
 *
 * It renders what the host half measured (`plugin/lib/storage-scan.js`) from the
 * report it wrote to `$DSH_HOME/storages/dsh-storage-panel/report.json`: what DSH
 * leaves on this SSD, what each thing costs, which conversation it belongs to, and
 * which parts can be reclaimed (through the OS trash, never unlink).
 *
 * `tests/build.mjs` concatenates this file into one scope with `live-data.mjs`,
 * `fetched.mjs` and `index.mjs`, so it imports nothing: `React`, `el` and `isArray`
 * are plain in-scope bindings, on the same contract `fetched.mjs` documents. Every
 * one of them is referenced from inside a function body only — the top level of this
 * file runs while the concatenated scope is still being initialised.
 *
 * The rule this panel exists to keep: **never claim something is safe when it is
 * not.**
 *
 *   - Sizes are printed exactly as the report measured them; nothing is re-measured
 *     or extrapolated. Percentages and bar widths are the only computed numbers,
 *     and both are derived from reported sizes and labelled as comparisons.
 *   - The scanner's `reason` strings are rendered verbatim; the panel never
 *     paraphrases them into something stronger.
 *   - A `confidence: 'low'` item reads as a suggestion ("低置信度 · 仅建议"), never
 *     as a recommendation.
 *   - A category whose `reclaim` is `'never'` (runtime binaries) is marked as
 *     not-to-be-deleted wherever it appears, and says why.
 *   - Subagent sessions are nested under the parent they were recovered from, so a
 *     reader can see that the two costs share one log.
 *
 * Wiring status, checked against the current `index.mjs` and its stylesheet:
 *
 * - New CSS classes (this file is the only source of them; the stylesheet must be
 *   extended before the panel looks finished):
 *     .dshcl-storage                view root
 *     .dshcl-storageSection         one section wrapper
 *     .dshcl-storageSummary         the top block (stats grid)
 *     .dshcl-storageStats           the stat grid
 *     .dshcl-storageStat            one stat cell
 *     .dshcl-storageStatLabel       the cell's label
 *     .dshcl-storageStatValue       the cell's value
 *     .dshcl-storageStatus          status/error banner
 *     .dshcl-storageStatusBusy      its loading tone
 *     .dshcl-storageStatusOk        its ready tone
 *     .dshcl-storageStatusError     its error tone
 *     .dshcl-storageStatusDetail    the muted part after "·"
 *     .dshcl-storageControls        the button cluster in a section head
 *     .dshcl-storageBtn             button override hook (see the reuse note below)
 *     .dshcl-storagePath            mono, breakable path or identifier text
 *     .dshcl-storageSize            a right-aligned measured size
 *     .dshcl-storageRow             one cost category row
 *     .dshcl-storageBar             bar track (the fill's width is inline)
 *     .dshcl-storageBarFill         bar fill
 *     .dshcl-storageReclaim         reclaim hint pill base
 *     .dshcl-storageReclaimNever    "do not delete" tone
 *     .dshcl-storageReclaimAll      "safe to regenerate" tone
 *     .dshcl-storageReclaimSome     "review" tone
 *     .dshcl-storageReclaimUnknown  "not stated by the scan" tone
 *     .dshcl-storageDetail          the nested detail list under a cost row
 *     .dshcl-storageDetailRow       one nested detail row
 *     .dshcl-storageDetailValue     that row's size
 *     .dshcl-storageWorkspace       the workspace path in a group head
 *     .dshcl-storageSession         one session row
 *     .dshcl-storageMeta            a muted facts line (session facts, selection)
 *     .dshcl-storageActions         a session row's button cluster
 *     .dshcl-storageSubs            the nested subagent list
 *     .dshcl-storageSubRow          one nested subagent row (indented)
 *     .dshcl-storagePlanRow         one reclaim plan item
 *     .dshcl-storagePlanRowLow      a low-confidence (suggestion-only) plan item
 *     .dshcl-storageReason          the scanner's reason text
 *     .dshcl-storageFoot            the plan's selection + trash footer
 *     .dshcl-storageArm             a select control that needs a second click
 *     .dshcl-storageArmOn           that control's armed state
 *   Rows and sections also carry `data-*` hooks for CSS and tests: `data-category`,
 *   `data-reclaim`, `data-plan-item`, `data-kind`, `data-confidence`, `data-guarded`,
 *   `data-selected`, `data-plan-kind`, `data-session-id`, `data-subagent`,
 *   `data-workspace`, `data-status`, `data-storage-section`, `data-storage-panel`.
 *
 * - Reused shared classes (no new rules needed): .dshcl-secHead, .dshcl-secVer,
 *   .dshcl-secSummary, .dshcl-notice, .dshcl-noticeTitle, .dshcl-empty,
 *   .dshcl-items, .dshcl-item, .dshcl-itemHead, .dshcl-itemTitle, .dshcl-pill,
 *   .dshcl-count, .dshcl-group, .dshcl-groupHead, .dshcl-liveDate, .dshcl-liveWarn,
 *   .dshcl-liveBtn, and the inline-list style CoverageNotice already uses.
 *   Buttons carry `dshcl-liveBtn dshcl-storageBtn`: the live section's button class
 *   is the base so buttons are usable and hoverable before the storage rules land,
 *   and the storage class is the override hook.
 *
 * - Dictionary keys added. The panel's keys are namespaced `storage.`; every string
 *   below is required unless marked optional (the optional ones are closed
 *   vocabularies whose zh/en fallbacks live in this file, and a dictionary entry
 *   with the same key wins over the fallback):
 *
 *     storage.title                   存储占用 / Storage on disk
 *     storage.status.idle             尚未读取报告 / Report not read yet
 *     storage.status.loading          正在读取报告… / Reading the report…
 *     storage.status.ready            报告已载入 / Report loaded
 *     storage.status.scanError        主机端扫描失败 / Host scan failed
 *     storage.status.readError        读取报告失败 / Could not read the report
 *     storage.refresh                 重新读取报告 / Reload report
 *     storage.refreshing              读取中… / Reading…
 *     storage.rescan                  请求重新扫描 / Rescan now
 *     storage.empty                   还没有存储报告。点下面的按钮让主机端扫描一次。 / No storage report yet. Use the button below to run a host-side scan.
 *     storage.summary.note            所有数字都来自主机端扫描报告，面板不做估算。 / Every number comes from the host scan report; the panel estimates nothing.
 *     storage.summary.total           磁盘占用合计 / Total on disk
 *     storage.summary.totalNote       各分类实测之和；未计量的分类不在其中。 / The sum of the measured categories; unmeasured ones are not included.
 *     storage.summary.reclaimable     可回收 / Reclaimable
 *     storage.summary.reclaimableNote 回收计划里所有条目的合计，不代表它们都已被确认可删。 / The sum of every item in the reclaim plan — not all of them are confirmed safe to delete.
 *     storage.summary.noPlan          报告里没有回收计划。 / The report carries no reclaim plan.
 *     storage.summary.generatedAt     扫描时间 / Scanned
 *     storage.summary.scanTime        扫描耗时 / Scan time
 *     storage.summary.ms              {n} 毫秒 / {n} ms
 *     storage.summary.sessions        会话 / Conversations
 *     storage.summary.sessionsValue   {n} 个（含 {subs} 个子会话） / {n} ({subs} subagents)
 *     storage.summary.home            DSH 目录 / DSH home
 *     storage.summary.workspace       工作区 / Workspace
 *     storage.reportError             扫描器报告了错误 / The scanner reported an error
 *     storage.cost.title              空间去向 / Where the space goes
 *     storage.cost.sub                按实测大小从大到小排列；条形是相对最大一项的比例，百分比是占已计量合计的比例。 / Largest measured first; each bar is relative to the biggest row and the percentage is of the measured total.
 *     storage.cost.share              占 {pct} / {pct} of the measured total
 *     storage.cost.detailNote         明细是实测的子目录；散落文件不单独列出，所以明细相加可能小于该行合计。 / Detail rows are the measured subdirectories; loose files are not listed separately, so they may add up to less than the row's total.
 *     storage.cost.unmeasured         本次扫描未计量 / not measured by this scan
 *     storage.cost.empty              报告里没有可分类的实测数据。 / The report has no measured categories.
 *     storage.cost.neverDetail        以下文件由 DSH 运行时使用：删除后 DSH 将无法运行。 / These files belong to the DSH runtime; deleting them stops DSH from running.
 *     storage.cost.attachments        {count} 个对象，其中 {orphans} 个没有任何会话引用（{size}） / {count} objects, {orphans} of them referenced by no session ({size})
 *     storage.cost.more               另有 {n} 项未显示 / {n} more not shown
 *     storage.cost.files              {n} 个文件 / {n} files
 *     storage.cost.profileActive      使用中 / in use
 *     storage.sessions.title          会话与占用 / Conversations and what they cost
 *     storage.sessions.sub            按工作区分组，组间与组内都按实测大小从大到小排列。 / Grouped by workspace; groups and rows are ordered by measured size, largest first.
 *     storage.sessions.shareNote      子会话与父会话共用同一份日志，因此列在父会话下面。 / Subagent sessions share the parent's log, so they are listed under it.
 *     storage.sessions.empty          报告里没有会话目录。 / The report lists no session directories.
 *     storage.sessions.unresolved     {n} 个子会话没能匹配到父会话，单独列出。 / {n} subagent sessions could not be matched to a parent and are listed on their own.
 *     storage.sessions.attributionOff 未能解压会话日志，子会话归属不可用。 / Session logs could not be decompressed, so subagent attribution is unavailable.
 *     storage.sessions.subCount       含 {n} 个子会话 / {n} subagents
 *     storage.group.unknown           未记录工作区 / No recorded workspace
 *     storage.group.subtotal          {sessions} 个会话 · {size} / {sessions} conversations · {size}
 *     storage.turns                   {n} 轮 / {n} turns
 *     storage.turnsUnknown            轮数未知 / turn count unknown
 *     storage.modified                最后修改 {date} / modified {date}
 *     storage.badge.pinned            已固定 / pinned
 *     storage.badge.archived          已归档 / archived
 *     storage.badge.unprojected       无投影 / no projection
 *     storage.badge.unprojectedTitle  这个会话没有缓存投影，标题与轮数无法读取。 / This session has no cached projection, so its title and turn count cannot be read.
 *     storage.badge.subagent          子会话 / subagent
 *     storage.badge.orphan            父会话未识别 / parent not identified
 *     storage.action.open             打开对话 / Open conversation
 *     storage.action.reveal           在访达中显示 / Show in Finder
 *     storage.subagent.otherCwd       运行目录 {cwd} / ran in {cwd}
 *     storage.plan.title              回收计划 / Reclaim plan
 *     storage.plan.sub                {n} 项 · 合计 {size} / {n} items · {size} total
 *     storage.plan.scope              计划只包含配置档案、浏览器缓存、无引用附件和已归档会话；运行时二进制不在其中。 / The plan only ever covers plugin profiles, browser cache, unreferenced attachments and archived sessions; runtime binaries are never in it.
 *     storage.plan.disclaimer         条目与理由都来自扫描器；标为「仅建议」的条目只是线索，不是结论。 / Items and reasons come from the scanner; anything marked “suggestion only” is a lead, not a verdict.
 *     storage.plan.empty              这份报告里没有可回收项。 / This report has nothing to reclaim.
 *     storage.plan.select             选择 / Select
 *     storage.plan.deselect           取消选择 / Deselect
 *     storage.plan.confirmSelect      再次点击确认 / Click again to confirm
 *     storage.plan.armTitle           这一项影响较大：需要点两次才会被选中。 / This item matters: it takes two clicks to select it.
 *     storage.plan.trash              移到废纸篓 / Move to Trash
 *     storage.plan.trashing           正在移到废纸篓… / Moving to Trash…
 *     storage.plan.trashNote          项目会被移到系统废纸篓，可在访达里「放回原处」还原。 / Items go to the OS Trash and can be put back from Finder.
 *     storage.plan.selected           已选 {n} 项 · {size} / {n} selected · {size}
 *     storage.result.title            上次回收结果 / Last reclaim result
 *     storage.result.moved            已移到废纸篓 {n} 项 / {n} moved to the Trash
 *     storage.result.failed           失败 {n} 项 / {n} failed
 *     storage.result.skipped          跳过 {n} 项 / {n} skipped
 *     storage.workdir.title         其他窗口的产物 / Files from other windows
 *     storage.workdir.sub           每个窗口在自己的工作目录里生成的文件… / What each window generated in its own working directory…
 *     storage.workdir.sessions     {n} 个会话 / {n} session(s)
 *     storage.workdir.contains     {n} 个子窗口已并入下方，不计入本行 {size} / {n} nested window(s) counted below, excluded here ({size})
 *     storage.workdir.dedupe       嵌套目录已去重，避免重复计算 {size} / Nested directories deduplicated; {size} counted once
 *     storage.workdir.notReclaimable 这些是你自己的项目文件，不列为可回收 / Your own project files; never offered for reclamation
 *     storage.workdir.flat          目录下没有子目录，文件直接在根目录 / No subdirectories; files sit in the root
 *     storage.workdir.allNested     全部在子窗口内 / all inside nested windows
 *     storage.workdir.missing       这个目录已经不在了 / This directory no longer exists
 *     storage.workdir.empty         没有记录到任何工作目录 / No working directory recorded
 *     storage.result.refreshHint      重新读取报告即可刷新上面的列表。 / Reload the report to refresh the list above.
 *
 *   Optional (closed vocabularies; the zh/en fallbacks are inline below, and a
 *   dictionary entry under the same key wins over the fallback):
 *     storage.category.runtimes      运行时二进制 / Runtime binaries
 *     storage.category.plugins       插件配置档案 / Plugin profiles
 *     storage.category.sessions      会话日志 / Session logs
 *     storage.category.attachments   附件对象 / Attachment objects
 *     storage.category.browserCache  浏览器缓存 / Browser cache
 *     storage.category.caches        缓存与索引 / Caches and indexes
 *     storage.category.workspace     工作区文件 / Workspace files
 *     storage.category.other         其他（未计量） / Other (not measured)
 *     storage.reclaim.never          不建议删除 / Do not delete
 *     storage.reclaim.all            可安全重建 / Safe to regenerate
 *     storage.reclaim.some           需要自行判断 / Review before deleting
 *     storage.reclaim.unknown        扫描器未标注 / Not stated by the scan
 *     storage.confidence.high        高置信度 / high confidence
 *     storage.confidence.medium      中置信度 / medium confidence
 *     storage.confidence.low         低置信度 · 仅建议 / low confidence · suggestion only
 *     storage.plan.kind.profile      配置档案 / Plugin profile
 *     storage.plan.kind.browserCache 浏览器缓存 / Browser cache
 *     storage.plan.kind.attachment   附件对象 / Attachment object
 *     storage.plan.kind.session      已归档会话 / Archived session
 *     storage.plan.kind.other        其他 / Other
 *
 * - Report fields consumed, all verbatim from `scanStorage()`/`planCleanup()`:
 *   version, generatedAt, scanMs, error, host, totals, grandTotal, categories,
 *   runtimes.children, profiles, sessions, subagents, attachments, browserCache,
 *   caches.breakdown, workspace, plan.items, plan.bytes, plan.byKind.
 *
 * @module dsh-changelog-panel/storage-panel
 */

// ── vocabulary ──────────────────────────────────────────────────────────────
// Closed vocabularies carry their zh/en fallback inline, exactly like
// `NOTE_CATEGORY_LABEL` in fetched.mjs: a dictionary entry under the same key wins,
// so the panel reads correctly before the dictionaries are extended and keeps
// reading correctly afterwards.

